import { GoogleGenAI, GenerateContentResponse, Type, FunctionDeclaration } from "@google/genai";
import { AppMode, MessageRole } from "../types";
import { jokeTool, weatherTool, learningTool, codeGeneratorTool, toolHandlers } from "./tools";

const API_KEY = process.env.API_KEY || "";

export class GeminiService {
  private ai: GoogleGenAI;

  constructor() {
    this.ai = new GoogleGenAI({ apiKey: API_KEY });
  }

  async sendMessage(
    message: string, 
    history: any[] = [], 
    mode: AppMode = AppMode.GENERAL,
    onThinking?: (thought: string) => void
  ) {
    // 1. Determine Model and Tools based on Mode
    // Guideline: Search is mutual exclusive with other tools
    const useSearch = mode === AppMode.NEWS || mode === AppMode.LEARNING;

    const tools: any[] = [];
    if (useSearch) {
      tools.push({ googleSearch: {} });
    } else {
      tools.push({
        functionDeclarations: [jokeTool, weatherTool, learningTool, codeGeneratorTool]
      });
    }

    const systemInstruction = `You are AI Nexus, a multi-talented AI assistant.
    Current Mode: ${mode}

    - When in NEWS mode, focus on providing current events using Google Search.
    - When in LEARNING mode, act as an AI/ML tutor. Use Search for facts and tool-calling for specific tutorials.
    - When in DEVELOPER mode, focus on explaining Function Calling (simple, parallel, composite).
    - Always maintain a friendly, professional tone.
    - For jokes, use the get_random_joke tool.
    - If a user asks for AI syntax, use the generate_tool_definition_snippet tool.
    - ALWAYS explain how you are using tools when in developer/learning modes to help users learn.`;

    try {
      // We use gemini-3-flash-preview for speed and efficiency in interactive tasks
      const response = await this.ai.models.generateContent({
        model: 'gemini-3-flash-preview',
        contents: [...history, { role: 'user', parts: [{ text: message }] }],
        config: {
          systemInstruction,
          tools,
          thinkingConfig: { thinkingBudget: mode === AppMode.DEVELOPER ? 1000 : 0 }
        },
      });

      let finalResponseText = response.text || "";
      const functionCalls = response.functionCalls;
      const groundingLinks = response.candidates?.[0]?.groundingMetadata?.searchEntryPoint?.renderedContent 
        ? [] // Simplification: we'll use groundingChunks if available
        : (response.candidates?.[0]?.groundingMetadata?.groundingChunks?.map(chunk => chunk.web).filter(Boolean) as any[]) || [];

      // Handle Function Calls (if any)
      if (functionCalls && functionCalls.length > 0) {
        const toolResponses = await Promise.all(
          functionCalls.map(async (fc) => {
            const handler = toolHandlers[fc.name];
            const result = handler ? await handler(fc.args) : { error: "Tool not found" };
            return {
              id: fc.id,
              name: fc.name,
              response: result
            };
          })
        );

        // Send tool results back to get final text
        const finalResult = await this.ai.models.generateContent({
          model: 'gemini-3-flash-preview',
          contents: [
            ...history,
            { role: 'user', parts: [{ text: message }] },
            { role: 'model', parts: functionCalls.map(fc => ({ functionCall: fc })) },
            { role: 'tool', parts: toolResponses.map(tr => ({ functionResponse: tr })) }
          ],
          config: { systemInstruction, tools }
        });

        return {
          text: finalResult.text,
          functionCalls,
          toolResponses,
          groundingLinks
        };
      }

      return {
        text: finalResponseText,
        groundingLinks,
        thinking: (response as any).candidates?.[0]?.content?.parts?.find((p: any) => p.thought)?.thought
      };

    } catch (error) {
      console.error("Gemini API Error:", error);
      throw error;
    }
  }
}

import React, { useState, useRef, useEffect } from 'react';
import { ChatMessage, MessageRole, AppMode } from '../types';
import { Icons } from '../constants';

interface ChatInterfaceProps {
  messages: ChatMessage[];
  onSend: (text: string) => void;
  isLoading: boolean;
  mode: AppMode;
}

