                <div className="mb-3 p-2 bg-slate-900/50 rounded-lg border border-slate-700/50 text-xs italic text-slate-400 font-mono">
                  <div className="flex items-center gap-1 mb-1 text-slate-500">
                    <Icons.Terminal />
                    <span>Thought Process</span>
                  </div>
                  {msg.thinking}
                </div>
              )}

              <div className="whitespace-pre-wrap text-sm leading-relaxed">
                {msg.text}
              </div>

              {/* Tool Execution Logs */}
              {msg.functionCalls && msg.functionCalls.length > 0 && (
                <div className="mt-4 pt-3 border-t border-slate-700/50 space-y-2">
                  <p className="text-[10px] font-bold text-slate-500 uppercase tracking-widest">System Events</p>
                  {msg.functionCalls.map((fc, i) => (
                    <div key={i} className="flex items-center gap-2 text-xs font-mono text-cyan-400 bg-cyan-950/30 p-2 rounded border border-cyan-800/30">
                      <Icons.Terminal />
                      <span>Executed Tool: <span className="font-bold underline">{fc.name}</span></span>
                    </div>
                  ))}
                </div>
              )}

              {/* Grounding Links */}
              {msg.groundingLinks && msg.groundingLinks.length > 0 && (
                <div className="mt-4 pt-3 border-t border-slate-700 space-y-2">
                  <p className="text-[10px] font-bold text-slate-500 uppercase tracking-widest">Sources</p>
                  <div className="flex flex-wrap gap-2">
                    {msg.groundingLinks.map((link, i) => (
                      <a 
                        key={i}
                        href={link.uri}
                        target="_blank"
                        rel="noopener noreferrer"
                        className="flex items-center gap-1.5 px-3 py-1.5 bg-slate-900 border border-slate-700 hover:border-indigo-500 rounded-full text-xs text-indigo-400 hover:text-indigo-300 transition-colors"
                      >
                        <Icons.External />
                        <span className="truncate max-w-[150px]">{link.title}</span>
                      </a>
                    ))}
                  </div>
                </div>
              )}
            </div>
