            <svg xmlns="http://www.w3.org/2000/svg" width="18" height="18" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2.5" strokeLinecap="round" strokeLinejoin="round"><line x1="22" y1="2" x2="11" y2="13"/><polygon points="22 2 15 22 11 13 2 9 22 2"/></svg>
          </button>
        </div>
      </form>
    </div>
  );
};

import React, { useState, useCallback, useMemo } from 'react';
import { ChatInterface } from './components/ChatInterface';
import { ChatMessage, MessageRole, AppMode } from './types';
import { GeminiService } from './services/geminiService';
import { Icons, LESSONS } from './constants';

const App: React.FC = () => {
  const [messages, setMessages] = useState<ChatMessage[]>([]);
  const [isLoading, setIsLoading] = useState(false);
  const [mode, setMode] = useState<AppMode>(AppMode.GENERAL);

  const gemini = useMemo(() => new GeminiService(), []);

  const handleSend = useCallback(async (text: string) => {
    const userMsg: ChatMessage = {
      id: Date.now().toString(),
      role: MessageRole.USER,
      text,
      timestamp: Date.now()
    };

    setMessages(prev => [...prev, userMsg]);
    setIsLoading(true);

    try {
      // Map history for Gemini API
      const history = messages.map(m => ({
        role: m.role,
        parts: [{ text: m.text }]
      }));

      const response = await gemini.sendMessage(text, history, mode);

      const modelMsg: ChatMessage = {
        id: (Date.now() + 1).toString(),
        role: MessageRole.MODEL,
        text: response.text || "I'm sorry, I couldn't process that.",
        timestamp: Date.now(),
        functionCalls: response.functionCalls,
        toolResponses: response.toolResponses,
        groundingLinks: response.groundingLinks,
        thinking: response.thinking
      };

      setMessages(prev => [...prev, modelMsg]);
    } catch (err) {
      console.error(err);
      setMessages(prev => [...prev, {
        id: 'error',
        role: MessageRole.MODEL,
        text: "Error: I encountered a problem connecting to the brain center.",
        timestamp: Date.now()
      }]);
    } finally {
      setIsLoading(false);
    }
  }, [messages, mode, gemini]);

  const changeMode = (newMode: AppMode) => {
    setMode(newMode);
    // Add a system-like message to confirm mode change
    const systemMsg: ChatMessage = {
      id: `sys-${Date.now()}`,
      role: MessageRole.MODEL,
      text: `Switching to ${newMode.toUpperCase()} mode. How can I help you in this context?`,
      timestamp: Date.now()
    };
    setMessages(prev => [...prev, systemMsg]);
  };

  return (
    <div className="flex h-screen bg-slate-950 text-slate-100 overflow-hidden font-sans">
      {/* Sidebar */}
      <aside className="w-80 bg-slate-900/50 border-r border-slate-800 flex flex-col hidden lg:flex">
        <div className="p-6 border-b border-slate-800">
          <h2 className="text-xs font-bold text-slate-500 uppercase tracking-widest mb-4">Command Center</h2>
          <nav className="space-y-2">
            {[
              { id: AppMode.GENERAL, icon: Icons.Robot, label: 'General Nexus' },
              { id: AppMode.NEWS, icon: Icons.News, label: 'Global Briefing' },
              { id: AppMode.LEARNING, icon: Icons.Search, label: 'AI/ML Academy' },
              { id: AppMode.DEVELOPER, icon: Icons.Code, label: 'Tool Lab' },
            ].map((item) => (
              <button
                key={item.id}
                onClick={() => changeMode(item.id)}
                className={`w-full flex items-center gap-3 px-4 py-3 rounded-xl text-sm font-medium transition-all ${
                  mode === item.id 
                    ? 'bg-indigo-600 text-white shadow-lg shadow-indigo-600/20' 
                    : 'text-slate-400 hover:bg-slate-800 hover:text-slate-200'
                }`}
              >
                <item.icon />
                {item.label}
              </button>
            ))}
          </nav>
        </div>

        <div className="flex-1 overflow-y-auto p-6">
          <h2 className="text-xs font-bold text-slate-500 uppercase tracking-widest mb-4">Guided Learning</h2>
          <div className="space-y-4">
            {LESSONS.map((lesson) => (
              <div 
                key={lesson.id} 
                onClick={() => handleSend(`Tell me about ${lesson.title}`)}
                className="group p-4 bg-slate-800/40 border border-slate-700/50 rounded-xl cursor-pointer hover:border-indigo-500/50 hover:bg-slate-800 transition-all"
              >
                <div className="flex justify-between items-start mb-1">
                  <h3 className="text-sm font-semibold group-hover:text-indigo-400">{lesson.title}</h3>
                  <span className={`text-[10px] px-2 py-0.5 rounded-full border ${
                    lesson.difficulty === 'Beginner' ? 'border-green-800 text-green-500' :
                    lesson.difficulty === 'Intermediate' ? 'border-yellow-800 text-yellow-500' :
                    'border-red-800 text-red-500'
                  }`}>
                    {lesson.difficulty}
                  </span>
                </div>
                <p className="text-xs text-slate-500 line-clamp-2">{lesson.description}</p>
                <div className="mt-3 flex flex-wrap gap-1">
                  {lesson.tags.map(tag => (
                    <span key={tag} className="text-[9px] px-1.5 py-0.5 bg-slate-900 rounded text-slate-400 uppercase tracking-tighter">
                      #{tag}
                    </span>
                  ))}
                </div>
              </div>
            ))}
          </div>
        </div>

        <div className="p-6 border-t border-slate-800 bg-slate-900">
          <div className="p-3 bg-indigo-500/5 rounded-xl border border-indigo-500/20">
            <p className="text-[10px] font-bold text-indigo-400 uppercase mb-1">Status</p>
            <p className="text-xs text-slate-400">Gemini 3 Pro Pipeline Active</p>
          </div>
        </div>
      </aside>

      {/* Main Chat Area */}
      <main className="flex-1 flex flex-col min-w-0">
        <ChatInterface 
          messages={messages} 
          onSend={handleSend} 
          isLoading={isLoading} 
          mode={mode} 
        />
      </main>

      {/* Tool Inspector Panel (Visible in Developer Mode) */}
      {mode === AppMode.DEVELOPER && (
        <aside className="w-80 border-l border-slate-800 bg-slate-950 p-6 overflow-y-auto hidden xl:block">
          <h2 className="text-xs font-bold text-slate-500 uppercase tracking-widest mb-6">Tool Inspector</h2>

          <div className="space-y-8">
            <section>
              <h3 className="text-sm font-semibold mb-3 flex items-center gap-2">
